/* Numera Academy — Lição em tela cheia: ideia, simulação passo a passo e questões de prática.
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Lição em tela cheia ---------- */
function introScreens(){const m=method(s.method),d=C.DEEP[m.id];return [
 {eyebrow:'A ideia central',title:m.short,body:`<p class="lead">${m.concept}</p><div class="formula big">${safe(m.formula)}</div>`},
 {eyebrow:'Antes de começar',title:'Quais condições precisam valer?',body:`<p class="lead">${d.requires}</p><div class="callout"><strong>Dica</strong><p>${safe(m.tip)}</p></div>`},
 {eyebrow:'Como executar',title:'O procedimento, passo a passo',body:`<ol class="numbered">${d.steps.map(t=>`<li>${safe(t)}</li>`).join('')}</ol>`},
 {eyebrow:'Critério de parada',title:'Quando parar?',body:`<p class="lead">${d.stop}</p>`},
 {eyebrow:'Olhar crítico',title:'O que pode dar errado?',body:`<p class="lead">${d.trap}</p><div class="example-box"><span class="eyebrow">Exemplo</span><p>${safe(m.example)}</p></div>`},
 {eyebrow:'Do raciocínio ao algoritmo',title:'Em pseudocódigo',body:`<pre class="pseudocode">${safe(d.pseudo)}</pre>`},
 {eyebrow:'Aulas em vídeo',title:'Quer ouvir alguém explicando?',body:`<p class="lead">Escolhemos aulas de ${m.title} de professores de Cálculo Numérico. Assista e depois volte para a simulação: ver o método rodando passo a passo ajuda a fixar o que a aula explicou.</p>${videoList(m.id,'in-player')}`}];}
function playerTop(segs,label,closeAct,closeAttrs){return `<div class="player-top"><button type="button" class="icon-btn" data-act="${closeAct}" ${closeAttrs} aria-label="Fechar e voltar">${icon('close')}</button><div class="player-progress" role="img" aria-label="${safe(label)}">${segs.map(c=>`<i class="${c}"></i>`).join('')}</div><span class="player-meta">${comboPips()}${coinChip()}<span class="xp-meta">✦ ${p.xp}</span></span></div>`;}
function levelSegs(){const l=s.q<4?0:s.q<8?1:2;return [0,1,2,3].map(j=>{const i=l*4+j;return p.completed[`c:${s.method}:${i}`]?'done':i===s.q?'current':'';});}
function introPlayer(){const sc=introScreens(),i=Math.min(s.introStep,sc.length-1),cur=sc[i],last=i===sc.length-1;return `<div class="player">${playerTop(sc.map((_,j)=>j<i?'done':j===i?'current':''),`Tela ${i+1} de ${sc.length}`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col"><span class="eyebrow">${cur.eyebrow}</span><h1 class="display">${cur.title}</h1>${cur.body}</div></div><div class="player-bar"><div class="player-bar-inner"><span class="bar-count">${i+1} de ${sc.length}</span><div class="answer-actions">${i?btn('Voltar','intro-prev','ghost'):''}${btn(last?'Ver o método em ação '+icon('arrow'):'Continuar','intro-next','primary')}</div></div></div></div>`;}
function simulationResult(){const m=s.method,d=C.DEEP[m],o={tolerance:1e-8,maxIterations:80};if(d.system){const {A,b}=M.parseSystem(d.system);return m==='gauss'?M.gauss(A,b,o):M.seidel(A,b,A.map(()=>0),o);}const fn=M.parseFunction(d.example);return m==='bisection'?M.bisection(fn,d.a,d.b,o):m==='falseposition'?M.falsePosition(fn,d.a,d.b,o):m==='fixedpoint'?M.fixedPoint(M.parseFunction(d.g),d.x0,o):m==='newton'?M.newton(fn,d.x0,o):M.secant(fn,d.x0,d.x1,o);}
function matrix(mat){return `<div class="matrix-wrap"><table class="matrix" aria-label="Matriz aumentada"><tbody>${mat.map(r=>`<tr>${r.map((x,i)=>`<td class="${i===r.length-1?'rhs':''}">${num(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function simulation(){const r=simulationResult(),d=C.DEEP[s.method],i=Math.min(s.sim,r.iterations.length-1),row=r.iterations[i];return `<div class="player">${playerTop(r.iterations.map((_,j)=>j<i?'done':j===i?'current':''),`Registro ${i+1} de ${r.iterations.length}`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col wide"><span class="eyebrow">Execução real · você controla o ritmo</span><h1 class="display">${d.system?'Acompanhe o sistema':'Siga as aproximações'}</h1><div class="sim-stage">${d.system?`<pre class="formula">${safe(d.system)}</pre>${row.matrix?matrix(row.matrix):`<div class="vector">${row.x.map((v,k)=>`<span>x${k+1}<b>${num(v)}</b></span>`).join('')}</div>`}`:s.method==='fixedpoint'?cobweb(M.parseFunction(d.g),r,row):graph(M.parseFunction(d.example),r,d,row)}</div><div class="step-explain"><h3>${row.i===0?'Condições iniciais':`Registro ${i+1} de ${r.iterations.length}`}</h3><p>${safe(row.detail)}</p>${typeof row.x==='number'?`<div class="formula">x ≈ ${num(row.x)} · ${s.method==='fixedpoint'?'|x − g(x)|':'|f(x)|'} = ${num(Math.abs(row.fx))}</div>`:row.residual!==undefined?`<div class="formula">resíduo máximo = ${num(row.residual)}</div>`:''}<p class="fine">${s.method==='falseposition'?`A faixa destacada é o intervalo [a, b] deste passo e a reta liga (a, f(a)) a (b, f(b)). O novo ponto é onde essa corda cruza o eixo.${row.kept?` Depois do corte, a ponta ${row.kept==='b'?'b':'a'} é mantida.`:''}`:s.method==='fixedpoint'?`Diagrama em teia: a curva é y = g(x) e a diagonal é y = x. Cada degrau sobe até g e volta à diagonal, que transforma g(xₖ) no próximo xₖ₊₁ (aqui g(x) = ${safe(d.g)}).`:s.method==='bisection'?'A faixa destacada é o intervalo usado neste passo. Metade da sua largura limita o erro do ponto médio, sob as hipóteses do método.':s.method==='newton'?'A reta tracejada é a tangente aproximada do passo selecionado. A derivada aqui é numérica.':s.method==='secant'?'A reta tracejada liga os dois pontos anteriores usados neste passo.':'Confira a atualização de cada linha e a ordem em que os valores são utilizados.'}</p></div></div></div><div class="player-bar"><div class="player-bar-inner"><div class="sim-controls">${btn('←','sim-prev','ghost round',`aria-label="Passo anterior" ${i===0?'disabled':''}`)}<input aria-label="Passo da simulação" id="sim-range" type="range" min="0" max="${r.iterations.length-1}" value="${i}">${btn('→','sim-next','ghost round',`aria-label="Próximo passo" ${i===r.iterations.length-1?'disabled':''}`)}</div><div class="answer-actions">${btn((worldOpen(s.method)?'Começar a praticar ':'Voltar à trilha ')+icon('arrow'),'sim-done','primary')}</div></div></div></div>`;}
function practice(){const id=`c:${s.method}:${s.q}`,task=C.TASKS[s.method][s.q],l=s.q<4?0:s.q<8?1:2;return `<div class="player">${playerTop(levelSegs(),`Nível ${l+1}: etapa ${s.q%4+1} de 4`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col"><span class="eyebrow">Nível ${l+1} · ${C.LEVELS[s.q]}</span><p class="coach">${safe(C.COACH[s.method][s.q]||'Agora vá além da fórmula: pense nas condições, no erro e em como validar o resultado.')}</p>${question(task,id,'next-course')}</div></div></div>`;}
function course(){if(s.tab==='intro')return introPlayer();if(s.tab==='simulate')return simulation();if(s.tab==='practice')return practice();return courseOverview();}
function taskFor(id){const a=id.split(':');if(a[0]==='c')return C.TASKS[a[1]][+a[2]];if(a[0]==='a')return C.ARENA[+a[1]];return C.CASES.find(c=>c.id===a[1]).tasks[+a[2]];}
function currentId(){return s.page==='review'?s.reviewId:s.page==='case'?`p:${s.caseId}:${s.caseQ}`:`c:${s.method}:${s.q}`;}
function question(task,id,nextAction){const completed=p.completed[id];let opts=task.options?.map((v,i)=>({v,i}));if(opts){const shift=[...id].reduce((n,c)=>n+c.charCodeAt(0),0)%opts.length;opts=opts.slice(shift).concat(opts.slice(0,shift));}const reward=id.startsWith('p:')?'+40 XP':id.startsWith('a:')?'+30 XP':'+20 XP',fb=s.feedback;
 return `<form id="quiz-form" class="quiz" data-id="${id}"><div class="quiz-meta">${tag(task.type==='choice'?'Raciocínio':'Aplicação numérica')}${completed?tag('✓ Concluída '+stars(completed.stars),'green'):tag(reward,'xp')}</div><h2 class="quiz-q">${safe(task.q.replace('DESAFIO FINAL: ',''))}</h2>${opts?`<div class="choices" role="group" aria-label="Alternativas">${opts.map((o,j)=>`<button type="button" class="choice ${s.selected===o.i?'selected':''}" data-act="select" data-index="${o.i}" aria-pressed="${s.selected===o.i}"><span class="choice-key">${String.fromCharCode(65+j)}</span><span>${safe(o.v)}</span></button>`).join('')}</div>`:`<label class="answer-label" for="answer">Seu resultado</label><div class="answer-line"><input id="answer" type="text" inputmode="decimal" autocomplete="off" placeholder="Ex.: 1,416667 ou 17/12" value="${safe(s.answer)}"><span>Use ao menos 4 casas decimais quando necessário. Frações como 17/12 também valem.</span></div>`}
 ${s.hint?`<div class="hint-box"><b>Dica.</b> ${safe(task.hint||task.wrong||'Identifique os dados, escolha a fórmula e calcule cada termo antes de substituir.')}</div>`:''}
 <div class="player-bar ${fb?(fb.ok?'is-ok':'is-bad'):''}"><div class="player-bar-inner">${fb?`<div class="sheet-msg" role="status"><b>${fb.ok?'Correto!':'Ainda não.'}</b><span>${safe(fb.message.replace(/^Correto\.\s*/,''))}</span></div>`:`<span class="bar-count">${completed?'Refazer melhora as estrelas; o XP é recebido uma vez.':'Sem cronômetro. Pedir dica também faz parte.'}</span>`}<div class="answer-actions">${fb?.ok?btn('Continuar '+icon('arrow'),nextAction,'primary'):`${btn(s.hint?'Dica aberta':'Dica','hint','ghost',s.hint?'disabled':'')}<button class="btn primary" type="submit" id="check-btn">${fb?'Tentar de novo':'Conferir'}</button>`}</div></div></div></form>`;}

